def poly(x, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(x))] + [np.prod(x[:, ii], axis=1) for j in range(1, d + 1) for ii in combinations_with_replacement(range(x.shape[1]), j)])

def rational(g, Y, i, j, mode, ridge):
    from scipy.optimize import least_squares
    from scipy.linalg import solve
    F = poly(g, 2)
    Fi = F[i]
    Z = aff(g)
    Yi = Y[i]
    n = len(i)
    d = Z.shape[1]
    penalty = np.r_[np.ones(d) * 0.03, np.ones(F.shape[1] - d)]

    def solve(D):
        M = Fi / D[i, None]
        return np.linalg.solve(M.T @ M + ridge * np.diag(penalty), M.T @ Yi)
    if mode == 'full':

        def den(a):
            return np.exp(np.clip(F[:, d:] @ a, -2, 2))
        seeds = [np.zeros(F.shape[1] - d)]
    elif mode == 'diag':

        def den(a):
            return 1 + g ** 2 @ a
        seeds = [np.zeros(g.shape[1]) + 0.03]
    else:

        def den(a):
            return 1 + (Z @ a) ** 2
        seeds = np.r_[np.eye(d) * 0.3, np.random.default_rng(42).normal(size=(5, d)) * 0.35]

    def obj(a):
        D = den(a)
        q = solve(D)
        return np.r_[Fi @ q / D[i] - Yi, 0.025 * a, np.sqrt(ridge * penalty) * q]
    best = None
    for a in seeds:
        p = least_squares(obj, a, bounds=(0, 2) if mode == 'diag' else (-2, 2), max_nfev=100)
        if best is None or p.cost < best.cost:
            best = p
    D = den(best.x)
    q = solve(D)
    return (F[j] @ q / D[j], np.mean(abs(Fi @ q / D[i] - Yi)), best.x)
